    const sessions = getSessionCount();
    const uptime = Math.round(process.uptime() * 100) / 100;

    return NextResponse.json(
      { status: 'ok', sessions, uptime, version: VERSION },
      { status: 200 }
    );
  } catch {
    return NextResponse.json({ status: 'error' }, { status: 500 });
  }
}

